namespace sv_849503b3a64c4795970264c15f985fdd.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public record StatusUpdate(DateTimeOffset Timestamp, string Description);

using sv_849503b3a64c4795970264c15f985fdd.Client.Services;

namespace sv_849503b3a64c4795970264c15f985fdd.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            "PKG-001",
            "In Transit",
            "Memphis, TN",
            DateTimeOffset.UtcNow.AddDays(2),
            new List<StatusUpdate>
            {
                new(DateTimeOffset.UtcNow.AddDays(-3), "Package picked up"),
                new(DateTimeOffset.UtcNow.AddDays(-2), "Arrived at sorting facility"),
                new(DateTimeOffset.UtcNow.AddDays(-1), "Departed Memphis, TN hub"),
            }),
        ["PKG-002"] = new ShipmentDetails(
            "PKG-002",
            "Delivered",
            "Austin, TX",
            DateTimeOffset.UtcNow.AddDays(-1),
            new List<StatusUpdate>
            {
                new(DateTimeOffset.UtcNow.AddDays(-5), "Package picked up"),
                new(DateTimeOffset.UtcNow.AddDays(-4), "In transit"),
                new(DateTimeOffset.UtcNow.AddDays(-2), "Out for delivery"),
                new(DateTimeOffset.UtcNow.AddDays(-1), "Delivered — signed by recipient"),
            }),
        ["PKG-003"] = new ShipmentDetails(
            "PKG-003",
            "Processing",
            "Seattle, WA",
            DateTimeOffset.UtcNow.AddDays(5),
            new List<StatusUpdate>
            {
                new(DateTimeOffset.UtcNow.AddHours(-6), "Label created"),
                new(DateTimeOffset.UtcNow.AddHours(-2), "Package received at origin facility"),
            }),
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

using System.Net.Http.Json;

namespace sv_849503b3a64c4795970264c15f985fdd.Client.Services;

/// <summary>
/// Client-side implementation that calls the server API over HTTP.
/// Used when running in WebAssembly.
/// </summary>
public class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        return (await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct))!;
    }
}

using sv_849503b3a64c4795970264c15f985fdd.Client.Services;

namespace sv_849503b3a64c4795970264c15f985fdd;

public static class ShipmentApiEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        app.MapGet("api/shipments/{trackingNumber}", async (
            string trackingNumber,
            IShipmentService shipmentService,
            CancellationToken ct) =>
        {
            try
            {
                var shipment = await shipmentService.GetShipmentAsync(trackingNumber, ct);
                return Results.Ok(shipment);
            }
            catch (KeyNotFoundException)
            {
                return Results.NotFound();
            }
        });
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_849503b3a64c4795970264c15f985fdd.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Status Updates</h3>
    <ul>
        @foreach (var update in _shipment.Updates)
        {
            <li><strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description</li>
        }
    </ul>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override Task OnParametersSetAsync()
    {
        // Cancel any in-flight request when the tracking number changes
        CancelPending();
        return LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        _loading = true;
        _errorMessage = null;
        _shipment = null;

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation away or disposal — silently abandon
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || ex.CancellationToken != ct)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (KeyNotFoundException ex)
        {
            Logger.LogWarning(ex, "Shipment not found: {TrackingNumber}", TrackingNumber);
            _errorMessage = $"No shipment found for tracking number \"{TrackingNumber}\".";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryLoad() => LoadShipmentAsync();

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

